def note_division_negative_row(note_name: str, chunks: list[str], joiner: str = '\n') -> dict:
    """
    One all-negative `ml_data` row for joined text verified to contain NO division boundary.

    Same shape as `note_division_row` but with empty spans: the chunks were not
    one divided original (a lone atomic note, two halves of one note, or two
    unrelated notes), so every position is a negative — teaching the model that
    "no boundary" is a legal answer. v1 datasets contained only seam-bearing
    rows, and models trained on them over-split on seam-free input.

    **Parameters**
    - `note_name` (*str*) — Provenance identifier (`'a+b'` for cross-stream joins).
    - `chunks` (*list[str]*) — Ordered texts joined into `text`.
    - `joiner` (*str*) — Separator used to build `text`.
    """
    return {'task': 'note_division', PROVENANCE_COLUMN: note_name,
            'text': joiner.join(chunks), 'spans': []}


def produce_note_division_negative_rows(sequences: Iterable[tuple[str, list[str]]],
                                        joiner: str = '\n') -> list[dict]:
    """
    Turn `(note_name, chunks)` sequences into validated all-negative rows (see `note_division_negative_row`).

    **Parameters**
    - `sequences` (*Iterable[tuple[str, list[str]]]*) — Boundary-free `(provenance, chunk texts)` pairs.
    - `joiner` (*str*) — Separator between chunks.
    """
    rows = [note_division_negative_row(name, chunks, joiner) for name, chunks in sequences]
    NOTE_DIVISION_SCHEMA.validate_rows(rows)
    return rows
